/* Small embedded portraits so WebGL can use them when opened from file:// (see photos.js for credits). */
window.GOL = window.GOL || { characters: [] };
GOL.thumbs = {"beethoven": "data:image/jpeg;base64,", "cox": "data:image/jpeg;base64,", "curie": "data:image/jpeg;base64,", "grandin": "data:image/jpeg;base64,", "hawking": "data:image/jpeg;base64,", "heumann": "data:image/jpeg;base64,", "johnson": "data:image/jpeg;base64,", "kaepernick": "data:image/jpeg;base64,", "kahlo": "data:image/jpeg;base64,", "keller": "data:image/jpeg;base64,", "king": "data:image/jpeg;base64,", "malala": "data:image/jpeg;base64,", "mandela": "data:image/jpeg;base64,", "parks": "data:image/jpeg;base64,", "singh": "data:image/jpeg;base64,", "turing": "data:image/jpeg;base64,", "wonder": "data:image/jpeg;base64,"};
GOL.thumbOf = function (c) {
  if (GOL.thumbs[c.id]) return GOL.thumbs[c.id];
  if (c.illus) return "data:image/svg+xml;charset=utf-8," + encodeURIComponent(GOL.illus(c.illus));
  return "";
};
